312	func (p *Parser) parseBlockStmt() (*ast.Node, error) {
313		block := &ast.Node{
314			Kind: ast.NodeBlockStmt,
315			Line: p.curToken.Line,
316			Col:  p.curToken.Col,
317		}
318	
319		p.nextToken() // consume '{'
320	
321		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
322			stmt, err := p.parseStatement()
323			if err != nil {
324				return nil, err
325			}
326			if stmt != nil {
327				block.Children = append(block.Children, stmt)
328			}
329			p.skipSemicolons()
330		}
331	
332		if p.curToken.Type != ast.TokenRBrace {
333			return nil, fmt.Errorf("expected '}'")
334		}
335	
336		p.nextToken() // consume '}'
337	
338		return block, nil
339	}
