555	func (p *Parser) parseFieldDecl() (*ast.Node, error) {
556		if p.curToken.Type != ast.TokenIdent {
557			return nil, fmt.Errorf("expected field name")
558		}
559	
560		fieldNode := &ast.Node{
561			Kind:  ast.NodeFieldDecl,
562			Value: p.curToken.Value,
563			Line:  p.curToken.Line,
564			Col:   p.curToken.Col,
565		}
566	
567		p.nextToken() // consume field name
568	
569		if p.curToken.Type != ast.TokenColon {
570			return nil, fmt.Errorf("expected ':' after field name")
571		}
572	
573		p.nextToken() // consume ':'
574	
575		if p.curToken.Type != ast.TokenIdent {
576			return nil, fmt.Errorf("expected field type")
577		}
578	
579		typeNode := &ast.Node{
580			Kind:  ast.NodeIdent,
581			Value: p.curToken.Value,
582			Line:  p.curToken.Line,
583			Col:   p.curToken.Col,
584		}
585		fieldNode.TypeAnnotation = p.curToken.Value // Store type annotation directly
586		fieldNode.Children = append(fieldNode.Children, typeNode)
587	
588		p.nextToken() // consume type
589	
590		return fieldNode, nil
591	}
