145	// checkStructDecl registers a struct definition
146	func (tc *TypeChecker) checkStructDecl(n *ast.Node) TypeInfo {
147		structName := n.Value
148		def := StructDef{
149			Name:   structName,
150			Fields: make(map[string]TypeInfo),
151		}
152	
153		// Extract field types from children
154		for _, child := range n.Children {
155			if child.Kind == ast.NodeFieldDecl {
156				fieldName := child.Value
157				// Field type is in TypeAnnotation or Children[0].Value
158				fieldType := UnknownType
159				if child.TypeAnnotation != "" {
160					fieldType = TypeFromAnnotation(child.TypeAnnotation)
161				} else if len(child.Children) > 0 {
162					// Type is in Children[0].Value
163					fieldType = TypeFromAnnotation(child.Children[0].Value)
164				}
165				def.Fields[fieldName] = fieldType
166			}
167		}
168	
169		tc.env.RegisterStruct(structName, def)
170		return UnitType
171	}
172	
173	// checkLetDecl validates variable declaration and registration
174	func (tc *TypeChecker) checkLetDecl(n *ast.Node) TypeInfo {
175		if len(n.Children) < 2 {
176			return UnknownType
177		}
178	
179		nameNode := n.Children[0]
180		valueNode := n.Children[1]
181	
182		// Determine the type of the variable
183		var varType TypeInfo
184	
185		// If there's a type annotation, use it
186		if nameNode.TypeAnnotation != "" {
187			varType = TypeFromAnnotation(nameNode.TypeAnnotation)
188			// Check value type matches declared type
189			inferredType := tc.inferType(valueNode)
190			if inferredType.Kind != TypeUnknown && !varType.Equals(inferredType) {
191				tc.addError(
192					fmt.Sprintf("type mismatch: expected %v, got %v", varType, inferredType),
193					n.Line, n.Col,
194				)
195			}
196		} else {
197			// No annotation: infer from the value expression
198			varType = tc.inferType(valueNode)
199		}
200	
201		// Register the variable
202		tc.env.Define(nameNode.Value, varType)
203		return UnitType
204	}
