294	// checkFieldAccess validates field access and returns field type
295	func (tc *TypeChecker) checkFieldAccess(n *ast.Node) TypeInfo {
296		if len(n.Children) == 0 {
297			return UnknownType
298		}
299	
300		// Get the object type
301		objType := tc.checkNode(n.Children[0])
302		fieldName := n.Value
303	
304		// Look up struct definition
305		if objType.Kind == TypeStruct {
306			if structDef, found := tc.env.LookupStruct(objType.StructName); found {
307				if fieldType, fieldExists := structDef.Fields[fieldName]; fieldExists {
308					return fieldType
309				}
310				tc.addError(
311					fmt.Sprintf("unknown field '%s' on struct '%s'", fieldName, objType.StructName),
312					n.Line, n.Col,
313				)
314				return UnknownType
315			}
316			tc.addError(fmt.Sprintf("unknown struct '%s'", objType.StructName), n.Line, n.Col)
317			return UnknownType
318		}
319	
320		// Object is not a struct
321		if objType.Kind != TypeUnknown {
322			tc.addError(
323				fmt.Sprintf("cannot access field '%s' on non-struct type %v", fieldName, objType),
324				n.Line, n.Col,
325			)
326		}
327		return UnknownType
328	}
