330	// checkCallExpr validates function call and returns return type
331	func (tc *TypeChecker) checkCallExpr(n *ast.Node) TypeInfo {
332		fnName := n.Value
333	
334		// Check for user-defined function
335		if fnDef, found := tc.env.LookupFunc(fnName); found {
336			// Validate argument count
337			if len(n.Children) != len(fnDef.ParamTypes) {
338				tc.addError(
339					fmt.Sprintf("function '%s' expects %d arguments, got %d", fnName, len(fnDef.ParamTypes), len(n.Children)),
340					n.Line, n.Col,
341				)
342			}
343			// Return the function's return type
344			return fnDef.ReturnType
345		}
346	
347		// Check for built-in functions
348		switch fnName {
349		case "print":
350			return UnitType
351		case "len":
352			return IntType
353		case "str":
354			return StringType
355		default:
356			tc.addError(fmt.Sprintf("unknown function '%s'", fnName), n.Line, n.Col)
357			return UnknownType
358		}
359	}
