361	// inferType infers the type of a node without modifying the environment
362	func (tc *TypeChecker) inferType(n *ast.Node) TypeInfo {
363		if n == nil {
364			return UnknownType
365		}
366	
367		switch n.Kind {
368		case ast.NodeIntLit:
369			return IntType
370		case ast.NodeBoolLit:
371			return BoolType
372		case ast.NodeStringLit:
373			return StringType
374		case ast.NodeStructLit:
375			// Infer struct type from the struct name
376			return StructType(n.Value)
377		case ast.NodeIdent:
378			// Look up variable type
379			if t, found := tc.env.Lookup(n.Value); found {
380				return t
381			}
382			return UnknownType
383		case ast.NodeBinaryExpr:
384			return tc.checkBinaryExpr(n)
385		case ast.NodeFieldAccess:
386			return tc.checkFieldAccess(n)
387		case ast.NodeCallExpr:
388			return tc.checkCallExpr(n)
389		default:
390			return UnknownType
391		}
392	}
393	
394	// checkStructLit validates struct initialization
395	func (tc *TypeChecker) checkStructLit(n *ast.Node) TypeInfo {
396		structName := n.Value
397	
398		// Look up struct definition
399		if structDef, found := tc.env.LookupStruct(structName); found {
400			// Validate field initializations
401			for _, child := range n.Children {
402				if child.Kind == ast.NodeFieldDecl {
403					fieldName := child.Value
404					if _, fieldExists := structDef.Fields[fieldName]; !fieldExists {
405						tc.addError(
406							fmt.Sprintf("unknown field '%s' in struct '%s'", fieldName, structName),
407							child.Line, child.Col,
408						)
409					}
410					// Check field value type if we have field type info
411					if len(child.Children) > 0 {
412						fieldValueType := tc.inferType(child.Children[0])
413						expectedType := structDef.Fields[fieldName]
414						if fieldValueType.Kind != TypeUnknown && expectedType.Kind != TypeUnknown && !fieldValueType.Equals(expectedType) {
415							tc.addError(
416								fmt.Sprintf("field '%s' type mismatch: expected %v, got %v", fieldName, expectedType, fieldValueType),
417								child.Line, child.Col,
418							)
419						}
420					}
421				}
422			}
423			return StructType(structName)
424		}
425	
426		// Struct not found
427		tc.addError(fmt.Sprintf("unknown struct '%s'", structName), n.Line, n.Col)
428		return UnknownType
429	}
