329	// genExpr generates IR for an expression and returns the operand
330	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
331		if node == nil {
332			return Operand{}, fmt.Errorf("nil expression")
333		}
334	
335		switch node.Kind {
336		case ast.NodeIntLit:
337			// Parse integer literal
338			var val int64
339			fmt.Sscanf(node.Value, "%d", &val)
340			return Operand{IsImm: true, ImmVal: val}, nil
341	
342		case ast.NodeIdent:
343			return Operand{Name: node.Value}, nil
344	
345		case ast.NodeBinaryExpr:
346			return g.genBinaryExpr(node)
347	
348		case ast.NodeCallExpr:
349			return g.genCallExpr(node)
350	
351		case ast.NodeFieldAccess:
352			return g.genFieldAccess(node)
353	
354		default:
355			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
356		}
357	}
358	
359	// genBinaryExpr generates IR for a binary expression
360	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
361		if len(node.Children) < 2 {
362			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
363		}
364	
365		left, err := g.genExpr(node.Children[0])
366		if err != nil {
367			return Operand{}, err
368		}
369	
370		right, err := g.genExpr(node.Children[1])
371		if err != nil {
372			return Operand{}, err
373		}
374	
375		result := g.newTemp()
376		op := g.opcodeFromOp(node.Value)
377	
378		g.emit(Instruction{
379			Op:   op,
380			Dest: result,
381			Src1: left,
382			Src2: right,
383		})
384	
385		return result, nil
386	}
387	
388	// genCallExpr generates IR for a function call
389	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
390		if len(node.Children) == 0 {
391			return Operand{}, fmt.Errorf("call expression requires function name")
392		}
393	
394		fnName := node.Children[0].Value
395	
396		// Emit parameters
397		for i := 1; i < len(node.Children); i++ {
398			argOp, err := g.genExpr(node.Children[i])
399			if err != nil {
400				return Operand{}, err
401			}
402			g.emit(Instruction{
403				Op:   OpParam,
404				Src1: argOp,
405			})
406		}
407	
408		// Emit call
409		result := g.newTemp()
410		g.emit(Instruction{
411			Op:   OpCall,
412			Dest: result,
413			Fn:   fnName,
414		})
415	
416		return result, nil
417	}
418	
419	// Helper functions
420	
421	func (g *Generator) newTemp() Operand {
422		temp := Operand{
423			IsTemp: true,
424			Name:   fmt.Sprintf("t%d", g.tempCount),
425		}
426		g.tempCount++
427		return temp
428	}
429	
430	func (g *Generator) newLabel(prefix string) string {
431		label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
432		g.labelCount++
433		return label
434	}
435	
436	func (g *Generator) emit(instr Instruction) {
437		if g.currentFn != nil {
438			g.currentFn.Body = append(g.currentFn.Body, instr)
439		} else {
440			g.program.Main = append(g.program.Main, instr)
441		}
442	}
443	
444	func (g *Generator) opcodeFromOp(op string) Opcode {
445		switch op {
446		case "+":
447			return OpAdd
448		case "-":
449			return OpSub
450		case "*":
451			return OpMul
452		case "/":
453			return OpDiv
454		case "==":
455			return OpEq
456		case "!=":
457			return OpNe
458		case "<":
459			return OpLt
460		case ">":
461			return OpGt
462		case "<=":
463			return OpLe
464		case ">=":
465			return OpGe
466		default:
467			return OpNoop
468		}
469	}
470	
471	// genStructDecl generates IR for a struct declaration
472	func (g *Generator) genStructDecl(node *ast.Node) error {
473		if node.Value == "" {
474			return fmt.Errorf("struct declaration must have a name")
475		}
476	
477		name := node.Value
478		fields := []string{}
479	
480		// Extract field names from children
481		for _, field := range node.Children {
482			if field.Kind == ast.NodeFieldDecl {
483				fields = append(fields, field.Value)
484			}
485		}
486	
487		// Store struct definition
488		g.structFields[name] = fields
489	
490		// Calculate struct size (8 bytes per field)
491		size := len(fields) * 8
492	
493		// Save current function context
494		prevFn := g.currentFn
495		g.currentFn = nil // Emit to Main context
496	
497		// Emit OpStructDef instruction
498		g.emit(Instruction{
499			Op:   OpStructDef,
500			Fn:   name,
501			Src1: Operand{IsImm: true, ImmVal: int64(size)},
502		})
503	
504		// Restore function context
505		g.currentFn = prevFn
506	
507		return nil
508	}
509	
510	// genFieldAccess generates IR for a field access expression (obj.field)
511	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
512		if len(node.Children) == 0 {
513			return Operand{}, fmt.Errorf("field access requires object expression")
514		}
515	
516		// Generate IR for object expression
517		objOp, err := g.genExpr(node.Children[0])
518		if err != nil {
519			return Operand{}, err
520		}
521	
522		fieldName := node.Value
523	
524		// Search for field offset in known structs
525		var offset int64
526		found := false
527		for _, fields := range g.structFields {
528			for i, f := range fields {
529				if f == fieldName {
530					offset = int64(i * 8)
531					found = true
532					break
533				}
534			}
535			if found {
536				break
537			}
538		}
539		// If not found, use offset 0 as fallback
540	
541		// Emit OpFieldLoad instruction
542		result := g.newTemp()
543		g.emit(Instruction{
544			Op:   OpFieldLoad,
545			Dest: result,
546			Src1: objOp,
547			Src2: Operand{IsImm: true, ImmVal: offset},
548		})
549	
550		return result, nil
551	}
